-- The New 50 collection: 15 perfumes on sale now beside the first six, and
-- the other 35 added hidden and marked coming soon, ready to switch on later.
--
-- Run this in the Supabase SQL Editor AFTER the website update that reads
-- these columns is live, so the hidden perfumes are never sold by mistake.
-- Safe to run twice: columns are added only once and no perfume is added twice.

-- "Coming soon": shown in the shop, but it cannot be added to the bag or
-- ordered until it is switched to "On sale" in Admin → Catalogue.
alter table public.products
  add column if not exists coming_soon boolean not null default false,
  add column if not exists audience text;

alter table public.products drop constraint if exists products_audience_check;
alter table public.products
  add constraint products_audience_check check (audience is null or audience in ('Men', 'Women', 'Unisex'));

comment on column public.products.coming_soon is 'Shown in the shop but not for sale yet (the order API refuses it).';
comment on column public.products.audience is 'Who the perfume is for: Men, Women or Unisex. Used by the shop filter and the scent quiz.';

-- The New 50. The 15 launched now are visible and on sale, after the first
-- six; the other 35 are hidden and coming soon. In Admin → Catalogue, make one
-- visible to show it as coming soon, then switch it to On sale when it is made.
-- Pictures are kept in the website: the studio photo of the current bottle
-- with the new name on its label (public/products/bottles/) and, where there
-- is one, a scene of the perfume's notes first (public/products/scenes/).
-- Replace any of them with a new photo in Admin → Catalogue.
insert into public.products
  (slug, name, description, price, image_url, gallery_urls, alt, notes, size_volume,
   fragrance_family, scent_profile, occasion, audience, coming_soon, active, display_order)
select v.*
from (values
  ('samrat', 'Samrat', 'Samrat opens with bright mandarin and a warm thread of cinnamon, then settles into smoky oud wrapped in vanilla and creamy sandalwood. Rich and regal, made for the evenings you want to be remembered.', 749, '/products/bottles/samrat.webp', array['/products/bottles/samrat.webp'], 'SAHUMäRIO Samrat Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Mandarin · Bergamot · Cinnamon · Oud · Vanilla · Sandalwood', '50 ml', 'Spicy oud', 'Rich, spiced and regal', 'Evenings, weddings and festivals', 'Men', false, true, 140),
  ('rajtilak', 'Rajtilak', 'A golden touch of saffron, like a king''s tilak, laid over smooth leather and dry cedarwood. Bergamot keeps it bright; black musk keeps it close.', 749, '/products/bottles/rajtilak.webp', array['/products/bottles/rajtilak.webp'], 'SAHUMäRIO Rajtilak Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Bergamot · Mandarin · Saffron (kesar) · Leather · Cedarwood · Black musk', '50 ml', 'Saffron leather', 'Golden saffron on smooth leather', 'Weddings, festivals and special evenings', 'Men', false, true, 130),
  ('shaurya', 'Shaurya', 'Crisp bergamot and lavender meet a dark trail of oud and vetiver. Calm on the surface and strong underneath, a confident scent for every day and late nights.', 749, '/products/bottles/shaurya.webp', array['/products/bottles/shaurya.webp'], 'SAHUMäRIO Shaurya Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Bergamot · Lemon · Lavender · Oud · Vetiver (khus) · Cedarwood', '50 ml', 'Aromatic woody', 'Lavender over smoky woods', 'Office to evening', 'Men', true, false, 1030),
  ('kunwar', 'Kunwar', 'Neroli and mandarin sparkle over soft suede leather and creamy sandalwood. Polished, light and easy to wear, with a quiet richness that lasts into the evening.', 749, '/products/bottles/kunwar.webp', array['/products/bottles/kunwar.webp'], 'SAHUMäRIO Kunwar Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Mandarin · Bergamot · Neroli · Leather · Sandalwood · White musk', '50 ml', 'Floral leather', 'Fresh orange blossom on soft suede', 'Daytime, office and dates', 'Men', true, false, 1040),
  ('maharaja', 'Maharaja', 'Maharaja pours dark rum over smoky oud, with a pinch of black pepper and a warm base of vetiver and sandalwood. Deep, rich and made for grand evenings.', 749, '/products/bottles/maharaja.webp', array['/products/bottles/maharaja.webp'], 'SAHUMäRIO Maharaja Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Mandarin · Orange · Black pepper · Rum · Oud · Vetiver (khus)', '50 ml', 'Boozy oud', 'Dark rum, oud and spice', 'Evenings, parties and celebrations', 'Men', true, false, 1050),
  ('ashwa', 'Ashwa', 'Juicy orange and a spark of cinnamon ride over rugged saddle leather, earthy vetiver and cedarwood. Bold and warm, with a touch of vanilla softening the finish.', 749, '/products/bottles/ashwa.webp', array['/products/bottles/ashwa.webp'], 'SAHUMäRIO Ashwa Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Orange · Bergamot · Cinnamon · Leather · Vetiver (khus) · Cedarwood', '50 ml', 'Spicy leather', 'Orange and cinnamon on saddle leather', 'Evenings and weekends', 'Men', true, false, 1060),
  ('narangi-elaichi', 'Narangi Elaichi', 'Sun-bright orange and fresh green cardamom over clean, transparent woods. Lively and easy: a fresh everyday scent with a spicy Indian twist.', 749, '/products/bottles/narangi-elaichi.webp', array['/products/bottles/narangi-elaichi.webp'], 'SAHUMäRIO Narangi Elaichi Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Orange · Bergamot · Cardamom · Cedarwood · White musk', '50 ml', 'Citrus spicy', 'Bright orange and green cardamom', 'Daytime, office and college', 'Men', true, false, 1070),
  ('hara-ananas', 'Hara Ananas', 'Juicy pineapple and zesty lemon lifted by fresh green basil, resting on cool vetiver and cedarwood. Bright, green and full of energy.', 749, '/products/bottles/hara-ananas.webp', array['/products/bottles/hara-ananas.webp'], 'SAHUMäRIO Hara Ananas Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Pineapple · Lemon · Bergamot · Basil · Vetiver (khus) · Cedarwood', '50 ml', 'Fruity aromatic', 'Juicy pineapple with fresh green basil', 'Daytime, summer and travel', 'Men', false, true, 100),
  ('nayak', 'Nayak', 'A clean, classic gentleman''s scent: mandarin and lavender with a touch of rosemary, over smooth cedarwood and vetiver. Fresh, neat and always right.', 749, '/products/bottles/nayak.webp', array['/products/bottles/nayak.webp'], 'SAHUMäRIO Nayak Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Mandarin · Bergamot · Rosemary · Lavender · Cedarwood · Vetiver (khus)', '50 ml', 'Aromatic fougère', 'Clean lavender, herbs and woods', 'Office, daytime and every day', 'Men', true, false, 1090),
  ('sheetal', 'Sheetal', 'As cooling as its name: crisp lemon and bergamot, fresh basil and neroli over light cedarwood and vetiver. Made for hot afternoons.', 749, '/products/bottles/sheetal.webp', array['/products/bottles/sheetal.webp'], 'SAHUMäRIO Sheetal Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Lemon · Bergamot · Basil · Neroli · Cedarwood · Vetiver (khus)', '50 ml', 'Citrus aromatic', 'Cool lemon, basil and neroli', 'Summer days, office and gym', 'Men', true, false, 1100),
  ('kali-elaichi', 'Kali Elaichi', 'Cardamom and cracked black pepper over bergamot and grapefruit, deepened with black musk and cedarwood. Spicy, dark and magnetic.', 749, '/products/bottles/kali-elaichi.webp', array['/products/bottles/kali-elaichi.webp'], 'SAHUMäRIO Kali Elaichi Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Bergamot · Grapefruit · Cardamom · Black pepper · Black musk · Cedarwood', '50 ml', 'Spicy woody', 'Cardamom and black pepper on dark musk', 'Evenings and cooler days', 'Men', false, true, 110),
  ('kesariya-rum', 'Kesariya Rum', 'Mandarin and saffron melt into a glass of dark rum, finished with vanilla, vetiver and sandalwood. Warm, festive and smooth.', 749, '/products/bottles/kesariya-rum.webp', array['/products/bottles/kesariya-rum.webp'], 'SAHUMäRIO Kesariya Rum Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Mandarin · Bergamot · Saffron (kesar) · Rum · Vanilla · Vetiver (khus)', '50 ml', 'Spicy gourmand', 'Saffron, rum and warm vanilla', 'Evenings, festivals and winter', 'Men', true, false, 1120),
  ('raat-mogra', 'Raat Mogra', 'Night-blooming jasmine sharpened with black pepper, over dry cedarwood and dark musk. A bold floral for men who like to stand out after dark.', 749, '/products/bottles/raat-mogra.webp', array['/products/bottles/raat-mogra.webp'], 'SAHUMäRIO Raat Mogra Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Bergamot · Mandarin · Black pepper · Jasmine · Cedarwood · Black musk', '50 ml', 'Floral spicy', 'Night jasmine with black pepper', 'Evenings and nights out', 'Men', true, false, 1130),
  ('nirmal', 'Nirmal', 'Pure and simple: sparkling bergamot, lemon and grapefruit with green rosemary over a soft cloud of clean musk. Like a fresh shirt on a bright morning.', 749, '/products/bottles/nirmal.webp', array['/products/bottles/nirmal.webp'], 'SAHUMäRIO Nirmal Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Bergamot · Lemon · Grapefruit · Rosemary · White musk · Cedarwood', '50 ml', 'Fresh aromatic', 'Pure, clean bergamot and rosemary', 'Every day, office and gym', 'Men', true, false, 1140),
