  ('chandan-mirch', 'Chandan Mirch', 'Creamy sandalwood warmed by a crack of black pepper and lifted by mandarin. Smooth, elegant and quietly confident.', 749, '/products/bottles/chandan-mirch.webp', array['/products/bottles/chandan-mirch.webp'], 'SAHUMäRIO Chandan Mirch Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Mandarin · Bergamot · Black pepper · Sandalwood · White musk', '50 ml', 'Woody spicy', 'Creamy sandalwood with black pepper', 'Every day and evenings', 'Men', false, true, 120),
