  ('mogra-oud', 'Mogra Oud', 'Heady mogra (jasmine) over rich oud, sandalwood and black musk. Opulent, deep and made for celebrations.', 749, '/products/scenes/mogra-oud.webp', array['/products/scenes/mogra-oud.webp', '/products/bottles/mogra-oud.webp'], 'SAHUMäRIO Mogra Oud Eau de Parfum 50 ml bottle among its notes: jasmine, oud', 'Bergamot · Mandarin · Jasmine · Oud · Sandalwood · Black musk', '50 ml', 'Floral oud', 'White jasmine on rich oud', 'Weddings, festivals and evenings', 'Unisex', false, true, 240),
  ('kesar-kasturi', 'Kesar Kasturi', 'Saffron and dark musk, two treasures of Indian perfumery, with bergamot, sandalwood and a touch of vanilla. Warm, rich and sensual.', 749, '/products/scenes/kesar-kasturi.webp', array['/products/scenes/kesar-kasturi.webp', '/products/bottles/kesar-kasturi.webp'], 'SAHUMäRIO Kesar Kasturi Eau de Parfum 50 ml bottle among its notes: kesar, black musk', 'Bergamot · Mandarin · Saffron (kesar) · Black musk · Sandalwood · Vanilla', '50 ml', 'Musky spicy', 'Saffron on dark musk', 'Evenings, weddings and winter', 'Unisex', false, true, 230),
  ('ras-oud', 'Ras Oud', 'Juicy raspberry against smoky oud, with black musk, vetiver and sandalwood. A modern oud: dark, fruity and bold.', 749, '/products/bottles/ras-oud.webp', array['/products/bottles/ras-oud.webp'], 'SAHUMäRIO Ras Oud Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Raspberry · Bergamot · Oud · Black musk · Vetiver (khus) · Cedarwood', '50 ml', 'Fruity oud', 'Raspberry over smoky oud', 'Evenings and parties', 'Unisex', true, false, 1380),
  ('champa-oud', 'Champa Oud', 'Creamy champa (magnolia) on velvety oud, black musk, vanilla and sandalwood. Soft at first, deep underneath.', 749, '/products/bottles/champa-oud.webp', array['/products/bottles/champa-oud.webp'], 'SAHUMäRIO Champa Oud Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Mandarin · Bergamot · Magnolia · Oud · Black musk · Vanilla', '50 ml', 'Floral oud', 'Creamy magnolia on velvet oud', 'Evenings, weddings and festivals', 'Unisex', true, false, 1390),
