  ('garba', 'Garba', 'Made for Navratri nights: rose and a splash of rum over warm sandalwood, black musk and vanilla. Festive, warm and full of life.', 749, '/products/bottles/garba.webp', array['/products/bottles/garba.webp'], 'SAHUMäRIO Garba Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Mandarin · Bergamot · Rose · Rum · Sandalwood · Black musk', '50 ml', 'Floral boozy', 'Rose and rum on warm woods', 'Navratri, festivals and evenings', 'Unisex', true, false, 1450),
  ('aadu-elaichi', 'Aadu Elaichi', 'Soft ripe peach with green cardamom, on sandalwood, white musk and cedarwood. Gentle, fresh and a little spicy.', 749, '/products/bottles/aadu-elaichi.webp', array['/products/bottles/aadu-elaichi.webp'], 'SAHUMäRIO Aadu Elaichi Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Peach · Mandarin · Cardamom · Sandalwood · White musk · Cedarwood', '50 ml', 'Fruity spicy', 'Soft peach with green cardamom', 'Every day and daytime', 'Unisex', true, false, 1460),
  ('kesar-phool', 'Kesar Phool', 'Saffron and neroli blossom on golden sandalwood, white musk and vetiver. Bright, warm and celebratory.', 749, '/products/bottles/kesar-phool.webp', array['/products/bottles/kesar-phool.webp'], 'SAHUMäRIO Kesar Phool Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Bergamot · Mandarin · Saffron (kesar) · Neroli · Sandalwood · White musk', '50 ml', 'Floral spicy', 'Saffron and orange blossom', 'Weddings, festivals and every day', 'Unisex', true, false, 1470),
  ('seb-kasturi', 'Seb Kasturi', 'Crisp green apple and bergamot over dark black musk and cedarwood. Fresh on top, deep and clean underneath.', 749, '/products/bottles/seb-kasturi.webp', array['/products/bottles/seb-kasturi.webp'], 'SAHUMäRIO Seb Kasturi Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Green apple · Bergamot · Black musk · Cedarwood', '50 ml', 'Fruity musky', 'Crisp green apple on dark musk', 'Daytime, college and evenings', 'Unisex', true, false, 1480),
  ('elaichi-phool', 'Elaichi Phool', 'Green cardamom and neroli blossom with lemon, on cool khus (vetiver) and cedarwood. Fresh, spicy and calming in the heat.', 749, '/products/bottles/elaichi-phool.webp', array['/products/bottles/elaichi-phool.webp'], 'SAHUMäRIO Elaichi Phool Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Lemon · Bergamot · Cardamom · Neroli · Vetiver (khus) · Cedarwood', '50 ml', 'Aromatic floral', 'Cardamom and neroli on cool khus', 'Summer, office and daytime', 'Unisex', true, false, 1490),
  ('raat-lavender', 'Raat Lavender', 'Lavender for the night: bergamot and lavender over black musk, cedarwood and a touch of vanilla. Calm, dark and sensual.', 749, '/products/bottles/raat-lavender.webp', array['/products/bottles/raat-lavender.webp'], 'SAHUMäRIO Raat Lavender Eau de Parfum 50 ml bottle with a navy label, in soft studio light', 'Bergamot · Mandarin · Lavender · Black musk · Vanilla · Cedarwood', '50 ml', 'Aromatic musky', 'Lavender at night on black musk', 'Evenings and nights', 'Unisex', true, false, 1500)
